trait InventoryGateway {                        // domain-facing facade
  def checkStock(sku: String): Future[Stock]
}

final class AkkaInventoryGateway(ref: ActorRef[Inventory.Command])
    extends InventoryGateway {
  implicit private val timeout: Timeout = 3.seconds   // ask fails with TimeoutException
  def checkStock(sku: String): Future[Stock] =
    ref.ask(Inventory.CheckStock(sku, _)).mapTo[Inventory.Stock]
}
